 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    nonempty_rows = [r for r in range(h) if any(grid[r])]
    if nonempty_rows and all(len({v for v in grid[r] if v}) == 1 for r in nonempty_rows):
        # Horizontal bands encode a cyclic sequence; blank rows are filled by
        # continuing the sequence of band colors.
        colors = [next(v for v in grid[r] if v) for r in nonempty_rows]
        period = len(colors)
        phase = nonempty_rows[0] % period
        by_residue = {r % period: next(v for v in grid[r] if v) for r in nonempty_rows}
        # Map residues from the observed consecutive sequence.
        for i, r in enumerate(nonempty_rows):
            by_residue[r % period] = colors[i]
        return [[by_residue[(r - phase) % period] if False else 0 for _ in range(w)] for r in range(h)] if False else [
            [by_residue.get(r % period, colors[(r - nonempty_rows[0]) % period]) for _ in range(w)]
            for r in range(h)
        ]

    # Diagonal tracks run down and right. Their offsets (column - row)
    # define one complete cycle of a repeating diagonal pattern.
    tracks = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                tracks[c - r] = value
    period = len(tracks)
    pattern = {offset % period: value for offset, value in tracks.items()}
    return [[pattern[(c - r) % period] for c in range(w)] for r in range(h)]
       ",
